$$\begin{array}{l}
  {\left. F(x) + C \right|_{a}^{b}{= \left\lbrack {F(b) + C} \right\rbrack - \left\lbrack {F(a) + C} \right\rbrack}} \\
  {\phantom{\left. F(x) + C \right|_{a}^{b}}{= F(b) + C - F(a) - C}} \\
  {\phantom{\left. F(x) + C \right|_{a}^{b}}{= F(b) - F(a)}}
  \end{array}$$

$$\begin{array}{l}
  {\int_{0}^{2}\left( x + e^{x} \right)dx = \left. \frac{1}{2}x^{2} + e^{x} \right|_{0}^{2}} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = \left\lbrack \frac{1}{2}(2)^{2} + e^{2} \right\rbrack - \left\lbrack \frac{1}{2}(0) + e^{0} \right\rbrack} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = 2 + e^{2} - 1} \\
  {\phantom{\int_{0}^{2}\left( x + e^{x} \right)dx} = e^{2} + 1}
  \end{array}$$

$$\begin{array}{l}
  {\frac{b - a}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{1}{n} + f\left( x_{2} \right) \cdot \frac{1}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{1}{n}} \right\rbrack = \frac{1}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{b - a}{n} + f\left( x_{2} \right) \cdot \frac{b - a}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{b - a}{n}} \right\rbrack} \\
  {\phantom{\frac{b - a}{b - a}\left\lbrack {f\left( x_{1} \right) \cdot \frac{1}{n} + f\left( x_{2} \right) \cdot \frac{1}{n} + \ldots + f\left( x_{n} \right) \cdot \frac{1}{n}} \right\rbrack} = \frac{1}{b - a}\left\lbrack {f\left( x_{1} \right)\Delta x + f\left( x_{2} \right)\Delta x + \ldots + f\left( x_{n} \right)\Delta x} \right\rbrack}
  \end{array}$$

$$\begin{array}{l}
  {\lim\limits_{n\rightarrow\infty}\left\lbrack \frac{f\left( x_{1} \right) + f\left( x_{2} \right) + \cdot \cdot \cdot + f\left( x_{n} \right)}{n} \right\rbrack = \frac{1}{b - a}\lim\limits_{n\rightarrow\infty}\left\lbrack {f\left( x_{1} \right)\Delta x + f\left( x_{2} \right)\Delta x + \cdot \cdot \cdot + f\left( x_{n} \right)\Delta x} \right\rbrack} \\
  {\phantom{\lim\limits_{n\rightarrow\infty}\left\lbrack \frac{f\left( x_{1} \right) + f\left( x_{2} \right) + \cdot \cdot \cdot + f\left( x_{n} \right)}{n} \right\rbrack} = \frac{1}{b - a}{\int_{a}^{b}{f(x)}}dx}
  \end{array}$$

$$\begin{array}{l}
  {{Area\ of}R = {\text{Area of the region under the graph of}f(x) - {Area\ of\ the\ region\ under\ the\ graph\ of}g(x)}} \\
  {\phantom{{Area\ of}R} = {\int_{a}^{b}{f(x)\mathit{dx} - {\int_{a}^{b}{g(x)\mathit{dx}}}}}} \\
  {\phantom{{Area\ of}R} = {\int_{a}^{b}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}}}
  \end{array}$$

$$\begin{array}{l}
  {{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = {\int_{1}^{2}{\lbrack{({2x - 1})} - {({x^{2} - 4})}\rbrack}\mathit{dx}}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = {\int_{1}^{2}{({- x^{2} + 2x + 3})\mathit{dx}}}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = \left. - \frac{1}{3}x^{3} + x^{2} + 3x \right|_{1}^{2}} \\
  {\phantom{\int_{1}^{2}{\left\lbrack f(x) - g(x) \right\rbrack\mathit{dx}}} = \left( {- \frac{8}{3} + 4 + 6} \right) - \left( {- \frac{1}{3} + 1 + 3} \right) = \frac{11}{3}}
  \end{array}$$

$$\begin{array}{l}
  {{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x} = \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - \underset{n{terms}}{\underset{︸}{\lbrack\overline{p}\Delta x + \overline{p}\Delta x + \cdots + \overline{p}\Delta x\rbrack}}} \\
  {\phantom{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x}{= \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - n\overline{p}\Delta x}} \\
  {\phantom{\lbrack D(x_{1}) - \overline{p}\rbrack\Delta x + \lbrack D(x_{2}) - \overline{p}\rbrack\Delta x + \cdots + \lbrack D(x_{n}) - \overline{p}\rbrack\Delta x}{= \lbrack D(x_{1}) + D(x_{2}) + \cdots + D(x_{n})\rbrack\Delta x - \overline{p}\overline{x}}}
  \end{array}$$

$$\begin{array}{ccl}
  {R(t)} & = & {{{Rate\ of\ income\ generation\ at\ any\ time}t}\qquad{In\ dollars\ per\ year}} \\
  {r} & = & {Interest\ rate\ compounded\ continuously} \\
  T & = & {{Term}\qquad{In\ years}}
  \end{array}$$

$$\begin{array}{lcl}
  P & = & {Size\ of\ each\ payment\ in\ the\ annuity} \\
  r & = & {Interest\ rate\ compounded\ continuously} \\
  T & = & {{Term\ of\ the\ annuity}({in\ years})} \\
  m & = & {Number\ of\ payments\ per\ year}
  \end{array}$$

$$\begin{array}{l}
  {A{= e^{\mathit{rT}}\int_{0}^{T}{R(t)e^{- rt}dt = e^{\mathit{rT}}\int_{0}^{T}{mPe^{- rt}dt}}}} \\
  {\phantom{A}{= mPe^{\mathit{rT}}{\left\lbrack {- \frac{e^{- rt}}{r}} \right\rbrack|}_{0}^{T} = mPe^{\mathit{rT}}\left\lbrack {- \frac{e^{- rT}}{r} + \frac{1}{r}} \right\rbrack}} \\
  {\phantom{A}{= \frac{\mathit{mP}}{r}\left( {e^{\mathit{rT}} - 1} \right)\qquad{{Since}e^{rT} \cdot e^{- rT} = 1}}}
  \end{array}$$
